To integrate the JSON dataset into an interactive line chart with D3.js library, you can follow these steps:
1. Load the JSON data using D3.json() function.
2. Parse the date string to a JavaScript Date object using d3.timeParse() function.
3. Set up the scales for the x and y axes using d3.scaleTime() and d3.scaleLinear() functions respectively.
4. Set up the line generator using d3.line() function.
5. Append the x and y axes to the chart using d3.axisBottom() and d3.axisLeft() functions respectively.
6. Draw the line chart using path element and the line generator.
7. Add zooming and hovering functionalities to the chart using d3.zoom() and d3.mouse() functions respectively.
Here is an example code snippet that demonstrates how to achieve this:
```javascript
// Load the JSON data
d3.json("data.json").then(function(data) {
  // Parse the date string to a JavaScript Date object
  var parseDate = d3.timeParse("%Y-%m-%d");
  data.forEach(function(d) {
    d.date = parseDate(d.date);
  });
  // Set up the scales for the x and y axes
  var xScale = d3.scaleTime()
    .domain(d3.extent(data, function(d) { return d.date; }))
    .range([0, width]);
  var yScale = d3.scaleLinear()
    .domain([0, d3.max(data, function(d) { return d.price; })])
    .range([height, 0]);
  // Set up the line generator
  var line = d3.line()
    .x(function(d) { return xScale(d.date); })
    .y(function(d) { return yScale(d.price); });
  // Append the x and y axes to the chart
  svg.append("g")
    .attr("transform", "translate(0," + height + ")")
    .call(d3.axisBottom(xScale));
  svg.append("g")
    .call(d3.axisLeft(yScale));
  // Draw the line chart
  svg.append("path")
    .datum(data)
    .attr("class", "line")
    .attr("d", line);
  // Add zooming functionality to the chart
  svg.call(d3.zoom()
    .scaleExtent([1, 10])
    .on("zoom", function() {
      svg.selectAll(".line")
        .attr("transform", d3.event.transform);
      svg.selectAll(".x.axis").call(d3.axisBottom(xScale).scale(d3.event.transform.rescaleX(xScale)));
      svg.selectAll(".y.axis").call(d3.axisLeft(yScale).scale(d3.event.transform.rescaleY(yScale)));
    }));
  // Add hovering functionality to the chart
  var focus = svg.append("g")
    .attr("class", "focus")
    .style("display", "none");
  focus.append("circle")
    .attr("r", 5);
  focus.append("text")
    .attr("x", 9)
    .attr("dy", ".35em");
  svg.append("rect")
    .attr("class", "overlay")
    .attr("width", width)
    .attr("height", height)
    .on("mouseover", function() { focus.style("display", null); })
    .on("mouseout", function() { focus.style("display", "none"); })
    .on("mousemove", mousemove);
  function mousemove() {
    var x0 = xScale.invert(d3.mouse(this)[0]),
        i = bisectDate(data, x0, 1),
        d0 = data[i - 1],
        d1 = data[i],
        d = x0 - d0.date > d1.date - x0 ? d1 : d0;
    focus.attr("transform", "translate(" + xScale(d.date) + "," + yScale(d.price) + ")");
    focus.select("text").text(d.price);
  }
});
```
