using System;
using System.Linq;
class Program
{
    static void Main(string[] args)
    {
        // Define Matrix A
        double[,] matrixA = { { 1, 2 }, { 3, 4 } };
        // Find the inverse of Matrix A
        double[,] inverseA = MatrixInverse(matrixA);
        // Generate Matrix B with random values between 0 and 1
        double[,] matrixB = MatrixRandom(2, 2);
        // Multiply Matrix A inverse with Matrix B to get Matrix C
        double[,] matrixC = MatrixMultiply(inverseA, matrixB);
        // Calculate the determinant of Matrix C
        double determinantC = MatrixDeterminant(matrixC);
        Console.WriteLine("Matrix A:");
        MatrixPrint(matrixA);
        Console.WriteLine("Inverse of Matrix A:");
        MatrixPrint(inverseA);
        Console.WriteLine("Matrix B:");
        MatrixPrint(matrixB);
        Console.WriteLine("Matrix C:");
        MatrixPrint(matrixC);
        Console.WriteLine("Determinant of Matrix C: " + determinantC);
    }
    static double[,] MatrixInverse(double[,] matrix)
    {
        int n = (int)Math.Sqrt(matrix.Length);
        double[,] inverse = new double[n, n];
        double determinant = MatrixDeterminant(matrix);
        if (determinant == 0)
        {
            throw new Exception("Matrix is not invertible");
        }
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                inverse[i, j] = Math.Pow(-1, i + j) * MatrixDeterminant(MatrixMinor(matrix, i, j)) / determinant;
            }
        }
        return MatrixTranspose(inverse);
    }
    static double[,] MatrixMinor(double[,] matrix, int row, int col)
    {
        int n = (int)Math.Sqrt(matrix.Length);
        double[,] minor = new double[n - 1, n - 1];
        int m = 0;
        int n = 0;
        for (int i = 0; i < n; i++)
        {
            if (i != row)
            {
                n = 0;
                for (int j = 0; j < n; j++)
                {
                    if (j != col)
                    {
                        minor[m, n] = matrix[i, j];
                        n++;
                    }
                }
                m++;
            }
        }
        return minor;
    }
    static double[,] MatrixTranspose(double[,] matrix)
    {
        int n = matrix.GetLength(0);
        int m = matrix.GetLength(1);
        double[,] transpose = new double[m, n];
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                transpose[j, i] = matrix[i, j];
            }
        }
        return transpose;
    }
    static double[,] MatrixRandom(int rows, int cols)
    {
        double[,] matrix = new double[rows, cols];
        Random random = new Random();
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                matrix[i, j] = random.NextDouble();
            }
        }
        return matrix;
    }
    static double[,] MatrixMultiply(double[,] matrixA, double[,] matrixB)
    {
        int n = matrixA.GetLength(0);
        int m = matrixB.GetLength(1);
        double[,] result = new double[n, m];
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                for (int k = 0; k < matrixA.GetLength(1); k++)
                {
                    result[i, j] += matrixA[i, k] * matrixB[k, j];
                }
            }
        }
        return result;
    }
    static double MatrixDeterminant(double[,] matrix)
    {
        int n = (int)Math.Sqrt(matrix.Length);
        double determinant = 0;
        if (n == 2)
        {
            determinant = matrix[0, 0] * matrix[1, 1] - matrix[0, 1] * matrix[1, 0];
        }
        else
        {
            for (int i = 0; i < n; i++)
            {
                determinant += Math.Pow(-1, i) * matrix[0, i] * MatrixDeterminant(MatrixMinor(matrix, 0, i));
            }
        }
        return determinant;
    }
    static void MatrixPrint(double[,] matrix)
    {
        int n = matrix.GetLength(0);
        int m = matrix.GetLength(1);
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                Console.Write(matrix[i, j] + " ");
            }
            Console.WriteLine();
        }
        Console.WriteLine();
    }
}
```
