import java.util.Scanner;
public class EquationSolver {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter the value of y: ");
        double y = input.nextDouble();

        double leftSide = 5 * Math.pow(y, 2) - 6 * y + 2;
        double rightSide = 4 * Math.pow(y, 2) + 5;

        if (leftSide == rightSide) {
            System.out.println("The value of y is " + y);
        } else {
            System.out.println("There is no solution for y.");
        }

        double discriminant = Math.pow(-6, 2) - 4 * 5 * (2 - 4 * Math.pow(y, 2) - 5);

        if (discriminant < 0) {
            System.out.println("The solution set is imaginary.");
            double imaginaryPart = Math.sqrt(-discriminant) / (2 * 5);
            System.out.println("y = " + (3 / 5.0 + imaginaryPart) + "i or y = " + (3 / 5.0 - imaginaryPart) + "i");
        }
    }
}
```
