Here's a Python code that uses dynamic programming to generate Catalan numbers:
def catalan(n):
    if n <= 1:
        return 1
    catalan = [0] * (n + 1)
    catalan[0] = 1
    catalan[1] = 1
    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]
    return catalan[n]

def main():
    i = 0
    while catalan(i) <= 1000:
        print(catalan(i))
        i += 1

if __name__ == '__main__':
    main()

