#include <iostream>
#include <fstream>
#include <sstream>
#include <map>
using namespace std;
map<string,string> dict;
void loadDictionary(string filename) {
    ifstream infile(filename.c_str());
    string line;
    while (getline(infile, line)) {
        istringstream iss(line);
        string word, phonemes;
        iss >> word >> phonemes;
        dict[word] = phonemes;
    }
}
string getPhonemes(string word) {
    map<string,string>::iterator it = dict.find(word);
    if (it != dict.end()) {
        return it->second;
    } else {
        return "";
    }
}
