import pandas as pd
from sklearn.metrics.pairwise import cosine_similarity
# Load the customer data into a Pandas DataFrame
customer_df = pd.json_normalize(data["customers"])
# Create a product/customer matrix where each row represents a product and each column represents a customer
product_customer_matrix = pd.DataFrame(columns=customer_df["id"], index=range(1, 8))
# Fill in the matrix with 1's where a customer has purchased a product, and 0's where they haven't
for i, row in customer_df.iterrows():
    for purchase in row["purchase_history"]:
        product_customer_matrix.at[purchase["product_id"], row["id"]] = 1
# Calculate the cosine similarity between each pair of customers
customer_similarity_matrix = pd.DataFrame(cosine_similarity(product_customer_matrix.T), columns=customer_df["id"], index=customer_df["id"])
# Get the top 3 most similar customers for each customer
similar_customers = {}
for customer_id in customer_df["id"]:
    similar_customers[customer_id] = list(customer_similarity_matrix[customer_id].sort_values(ascending=False).head(4).index)[1:]
# Get the products that the similar customers have purchased that the current customer hasn't
recommended_products = {}
for customer_id in customer_df["id"]:
    purchased_products = set([purchase["product_id"] for purchase in customer_df[customer_df["id"] == customer_id]["purchase_history"].iloc[0]])
    recommended_products[customer_id] = []
