        recommended_products[customer_id].extend(list(similar_customer_purchases - purchased_products))
    recommended_products[customer_id] = list(set(recommended_products[customer_id]))
# Print the recommended products for each customer
for customer_id in customer_df["id"]:
    print(f"Recommended products for customer {customer_id}: {recommended_products[customer_id]}")
