	// Extract alcohol type
	typeRegex := regexp.MustCompile(`[a-zA-Z]+\s+[a-zA-Z]+`)
	alcoholType := typeRegex.FindString(label)

	// Extract flavor profile
	flavorRegex := regexp.MustCompile(`\b\w+ finish\b`)
	flavorProfile := flavorRegex.FindString(label)

	fmt.Printf("Alcohol Type: %s\n", alcoholType)
	fmt.Printf("Flavor Profile: %s\n", flavorProfile)
}

