How can I find the next number in a series where the difference between the current and previous number is a prime number and the next number is divisible by 6? Here is the PHP code I have so far:
$num1 = 5;
$num2 = 11;
$num3 = 17;
while(true){
    $diff1 = $num2 - $num1;
    $diff2 = $num3 - $num2;
    if (isPrime($diff2) && $num3 % 6 == 0){
        echo "The next number is: " . ($num3 + $diff2) . "\n";
        break;
    } elseif (isPrime($diff1) && $num2 % 6 == 0){
        echo "The next number is: " . ($num2 + $diff1) . "\n";
        $num1 = $num2;
        $num2 = $num2 + $diff1;
    } else {
        $num1 = $num2;
        $num2 = $num3;
        $num3 = $num2 + rand(1, 10);
    }
}
function isPrime($num) {
    if ($num <= 1) {
        return false;
    }
    for ($i = 2; $i <= sqrt($num); $i++) {
        if ($num % $i == 0) {
            return false;
        }
    }
    return true;
}

